CREATE TABLE observations (id VARCHAR(100) PRIMARY KEY, tenant_id UUID NOT NULL, hospitalization_id VARCHAR(100) NOT NULL REFERENCES hospitalizations(id), kind VARCHAR(50) NOT NULL, observed_at TIMESTAMPTZ NOT NULL, value TEXT NOT NULL, notes TEXT, created_at TIMESTAMPTZ NOT NULL, created_by VARCHAR(100) NOT NULL);
CREATE TABLE discharge_summaries (id VARCHAR(100) PRIMARY KEY, tenant_id UUID NOT NULL, hospitalization_id VARCHAR(100) NOT NULL REFERENCES hospitalizations(id), status VARCHAR(30) NOT NULL, clinical_summary TEXT NOT NULL, treatments TEXT, home_instructions TEXT, medications JSONB NOT NULL DEFAULT '[]'::jsonb, follow_up_date TIMESTAMPTZ, portal_shared BOOLEAN NOT NULL DEFAULT FALSE, portal_shared_at TIMESTAMPTZ, pdf_generated BOOLEAN NOT NULL DEFAULT FALSE, pdf_generated_at TIMESTAMPTZ, finalized_at TIMESTAMPTZ, finalized_by VARCHAR(100), amends_summary_id VARCHAR(100), amendment_reason TEXT, notes TEXT, created_at TIMESTAMPTZ NOT NULL, created_by VARCHAR(100) NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE INDEX observations_tenant_hospitalization_time_idx ON observations(tenant_id,hospitalization_id,observed_at); CREATE INDEX discharge_summaries_tenant_hospitalization_status_idx ON discharge_summaries(tenant_id,hospitalization_id,status); CREATE INDEX discharge_summaries_tenant_amends_idx ON discharge_summaries(tenant_id,amends_summary_id);
ALTER TABLE observations ENABLE ROW LEVEL SECURITY; ALTER TABLE observations FORCE ROW LEVEL SECURITY; ALTER TABLE discharge_summaries ENABLE ROW LEVEL SECURITY; ALTER TABLE discharge_summaries FORCE ROW LEVEL SECURITY;
CREATE POLICY observations_tenant ON observations USING (tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK (tenant_id=current_setting('app.tenant_id',true)::uuid); CREATE POLICY discharge_summaries_tenant ON discharge_summaries USING (tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK (tenant_id=current_setting('app.tenant_id',true)::uuid);
